pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address to, uint256 amount) internal {
        vm.assume(to != address(0));
        vm.assume(amount <= 1e30);
        uint256 beforeSender;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeSender = __r; } catch { return; }
        uint256 beforeTo;
        try c.balanceOf(to) returns (uint256 __r) { beforeTo = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
            // ok should be true per spec, but we won't rely on it
        } catch {
            reverted = true;
        }
        uint256 afterSender;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterSender = __r; } catch { return; }
        uint256 afterTo;
        try c.balanceOf(to) returns (uint256 __r) { afterTo = __r; } catch { return; }
        assertTrue(reverted
                ? (afterSender == beforeSender && afterTo == beforeTo)
                : (beforeSender >= amount && afterSender + amount == beforeSender && afterTo == beforeTo + amount));
    }

    function testFuzz_run(address to, uint256 amount) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, amount);
    }

    receive() external payable {}
}
